import { ProfilePatch } from './types';
export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) throw new Error('invalid profile');
  const prototype = Object.getPrototypeOf(input);
  if (prototype !== Object.prototype && prototype !== null) throw new Error('invalid profile');
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') throw new Error('invalid profile');
  }

  const fields = input as Record<string, unknown>;
  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    const value = fields.displayName;
    if (value === null) {
      displayName = { kind: 'set', value: null };
    } else {
      if (typeof value !== 'string') throw new Error('invalid profile');
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > 40) throw new Error('invalid profile');
      displayName = { kind: 'set', value: trimmed };
    }
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    const value = fields.tags;
    if (value === null) {
      tags = { kind: 'set', value: [] };
    } else {
      if (!Array.isArray(value) || value.length > 5) throw new Error('invalid profile');
      const strings: string[] = [];
      const seen = new Set<string>();
      for (const tag of value) {
        if (typeof tag !== 'string') throw new Error('invalid profile');
        const trimmed = tag.trim();
        if (trimmed.length < 1 || trimmed.length > 12 || seen.has(trimmed)) throw new Error('invalid profile');
        seen.add(trimmed);
        strings.push(trimmed);
      }
      tags = { kind: 'set', value: strings };
    }
  }
  return { displayName, tags };
}
EOF
cat >> checks/public.cjs <<'EOF'

// Successful patches preserve omitted fields and normalize without mutating input.
const profile = { displayName: 'before', tags: ['old'] };
const patches = new ProfileService(profile);
const oldTags = profile.tags;
assert.strictEqual(patches.patch({}), profile);
assert.strictEqual(profile.tags, oldTags);
const inputTags = Object.freeze([' one ', 'two']);
const input = Object.freeze({ displayName: '  Alice  ', tags: inputTags });
assert.deepEqual(patches.patch(input), { displayName: 'Alice', tags: ['one', 'two'] });
assert.deepEqual(input, { displayName: '  Alice  ', tags: [' one ', 'two'] });
assert.notStrictEqual(profile.tags, inputTags);
assert.deepEqual(patches.patch({ displayName: null }), { displayName: null, tags: ['one', 'two'] });
assert.deepEqual(patches.patch({ tags: null }), { displayName: null, tags: [] });
assert.deepEqual(patches.patch({ tags: [] }), { displayName: null, tags: [] });
assert.deepEqual(patches.patch(Object.assign(Object.create(null), { displayName: ' name ' })),
  { displayName: 'name', tags: [] });
assert.deepEqual(patches.patch({ displayName: ' ' + 'n'.repeat(40) + ' ', tags: [' tttttttttttt ', 'b', 'c', 'd', 'e'] }),
  { displayName: 'n'.repeat(40), tags: ['t'.repeat(12), 'b', 'c', 'd', 'e'] });

// Invalid patches must not partially commit a valid field.
const invalidInputs = [
  null, undefined, 1, 'name', true, [], () => {}, new Date(),
  Object.create({ displayName: 'inherited' }),
  { extra: true }, { displayName: 'new', extra: true },
  { [Symbol('extra')]: true }, Object.defineProperty({}, 'extra', { value: true }),
  ...[undefined, 1, false, {}, [], '', '   ', 'n'.repeat(41)].map(displayName => ({ displayName, tags: ['valid'] })),
  ...[undefined, 1, false, {}, 'tag', [1], [null], [''], ['  '], ['t'.repeat(13)],
    ['a', ' a '], ['a', 'b', 'c', 'd', 'e', 'f'], new Array(1), ['valid', 2]]
    .map(tags => ({ displayName: 'new', tags })),
];
for (const invalid of invalidInputs) {
  const stored = { displayName: 'before', tags: ['old'] };
  const storedTags = stored.tags;
  const subject = new ProfileService(stored);
  assert.throws(() => subject.patch(invalid), { name: 'Error', message: 'invalid profile' });
  assert.deepEqual(stored, { displayName: 'before', tags: ['old'] });
  assert.strictEqual(stored.tags, storedTags);
}
const callerTags = ['fresh'];
patches.patch({ tags: callerTags });
callerTags[0] = 'changed';
assert.deepEqual(profile.tags, ['fresh']);
EOF
